const tomorrow = new Date(Date.now()+86400000).toISOString().slice(0,10);

const initialState = {
  tab: "home",
  lang: localStorage.getItem("lume_lang") || "en",
  category: "Signature",
  selectedMenuIds: [],
  menuDetailId: null,
  paymentMethod: "card",
  selectedAreaId: null,
  spaceDetailId: null,
  spaceReturnTab: "home",
  reservationStep: 0,
  reservationDraft: {date:tomorrow,time:"19:00",guests:2,occasion:"",name:"",phone:"",email:""},
  reservationErrors: {},
  reservationRequests: [],
  conciergeHistory: [],
  conciergePlan: null,
  conciergeSpaceIds: [],
  conciergeNextAction: null,
  conciergeBusy: false
};

let state = structuredClone(initialState);
const listeners = new Set();

export const store = {
  get(){ return state; },
  set(patch){
    state = {...state, ...patch};
    if (patch.lang) localStorage.setItem("lume_lang", patch.lang);
    listeners.forEach(fn => fn(state));
  },
  update(updater){
    state = updater(state);
    if (state.lang) localStorage.setItem("lume_lang", state.lang);
    listeners.forEach(fn => fn(state));
  },
  subscribe(fn){ listeners.add(fn); return () => listeners.delete(fn); }
};

