  return '<button type="button" class="payment-method '+(state.paymentMethod===method?"active":"")+'" data-action="payment-method" data-method="'+method+'"><strong>'+escapeHtml(title)+'</strong><span>'+escapeHtml(sub)+'</span></button>';
