export function requestedSpaceIds(message){
  const text=String(message||"").toLowerCase();
  const ids=[];
  const wantsBrowse=/(photo|photos|image|images|gallery|space|spaces|zone|zones|фото|фотограф|галере|пространств|зон|ảnh|hình|không gian)/i.test(text);
  if(!wantsBrowse) return ids;

  const wantsAll=/(all|every|compare|все|всех|сравн|tất cả|so sánh)/i.test(text);
  if(wantsAll) return areaIds();

  if(/sky\s*dining|dining|дайнинг/i.test(text)) ids.push("dining");
