import { MODEL, areaIds, buildPrompt, cleanText, menuIds, normalizeNextAction, normalizePlan, normalizeSpaceCardIds, requestedSpaceIds, safeHistory, safeSpaceBrowseReply } from "./domain.js";

function json(data,status=200){
  return new Response(JSON.stringify(data),{
    status,
    headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}
  });
}

function extractJson(value){
  const raw=typeof value==="string"?value:JSON.stringify(value==null?{}:value);
  const first=raw.indexOf("{"),last=raw.lastIndexOf("}");
  if(first<0||last<first) throw new Error("Model did not return JSON");
  return JSON.parse(raw.slice(first,last+1));
}

export async function handleConcierge(request,env){
  let body;
  try{body=await request.json();}catch{return json({error:"invalid_json"},400);}
  const message=cleanText(body?.message,1200);
  if(!message) return json({error:"message_required"},400);
  if(!env.AI) return json({error:"ai_binding_unavailable"},503);

  const history=safeHistory(body?.history);
  const prompt=buildPrompt({message,lang:body?.lang,history,context:body?.context&&typeof body.context==="object"?body.context:{}});

  try{
    const ids=menuIds();
    const spaces=areaIds();
    const result=await env.AI.run(MODEL,{
      messages:[
        {role:"system",content:"You are LUME Concierge. Follow the supplied venue facts, photo-card rules, conversion rules and truth rules exactly."},
        {role:"user",content:prompt}
      ],
      response_format:{
        type:"json_schema",
        json_schema:{
          type:"object",
          properties:{
            reply:{type:"string"},
            spaceCardIds:{type:"array",items:{type:"string",enum:spaces},maxItems:4},
            nextAction:{type:"string",enum:["explore_spaces","menu","reserve","ask_details"]},
            plan:{
              type:"object",
              properties:{
                title:{type:"string"},
                areaId:{type:"string",enum:spaces},
                experienceId:{type:"string",enum:["romantic","sunset","family","private"]},
                time:{type:"string"},
                guests:{type:"number"},
                mood:{type:"string"},
                pairing:{type:"string"},
                reason:{type:"string"},
                menuItemIds:{type:"array",items:{type:"string",enum:ids}}
              },
              required:["title","areaId","experienceId","time","guests","mood","pairing","reason","menuItemIds"]
            }
          },
          required:["reply","spaceCardIds","nextAction"]
        }
      },
      max_tokens:850,
      temperature:0.25
    });

    const raw=result?.response ?? result?.choices?.[0]?.message?.content ?? result;
    const parsed=raw&&typeof raw==="object"&&!Array.isArray(raw)?raw:extractJson(raw);
    let reply=cleanText(parsed?.reply,1000);
    if(!reply) throw new Error("Empty reply");

    const forcedSpaceIds=requestedSpaceIds(message);
    const modelSpaceIds=normalizeSpaceCardIds(parsed?.spaceCardIds);
    const spaceCardIds=normalizeSpaceCardIds([...forcedSpaceIds,...modelSpaceIds]);
    const refusalPattern=/(cannot|can't|unable|text[- ]based|do not have the ability|не могу.{0,30}(фото|фотограф|изображ)|не умею.{0,30}(фото|изображ)|không thể.{0,30}(ảnh|hình))/i;
    if(forcedSpaceIds.length && refusalPattern.test(reply)){
      reply=safeSpaceBrowseReply(body?.lang);
    }

    return json({
      reply,
      plan:normalizePlan(parsed?.plan),
      spaceCardIds,
      nextAction:forcedSpaceIds.length?"explore_spaces":normalizeNextAction(parsed?.nextAction),
      source:"workers-ai",
      model:MODEL
    });
  }catch(error){
    console.error("LUME concierge inference failed",error);
    return json({error:"concierge_inference_failed"},502);
  }
}

